import { test, expect } from '@playwright/test';

test.describe('Browser Push Notification for Urgent Alerts', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display browser push notification when urgent alert is received', async ({ page }) => {
    // Intercept the push notification API call
    await page.route('**/api/notifications/urgent', (route) => {
      route.continue();
    });

    // Click the button to trigger an urgent alert
    const alertButton = page.getByRole('button', { name: /trigger urgent alert/i });
    await expect(alertButton).toBeVisible();
    await alertButton.click();

    // Wait for the notification to be processed
    await page.waitForTimeout(500);

    // Verify the notification appears in the browser
    const notification = page.getByText(/urgent alert received/i);
    await expect(notification).toBeVisible();

    // Verify the notification has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify the notification has a dismiss action
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify the notification has a notification icon
    const notificationIcon = page.getByRole('img', { name: /notification icon/i });
    await expect(notificationIcon).toBeVisible();
  });

  test('should handle multiple urgent alerts and notification stacking', async ({ page }) => {
    // Intercept the push notification API call
    await page.route('**/api/notifications/urgent', (route) => {
      route.continue();
    });

    // Trigger the first urgent alert
    const alertButton1 = page.getByRole('button', { name: /trigger urgent alert/i });
    await expect(alertButton1).toBeVisible();
    await alertButton1.click();

    // Wait for the first notification
    await page.waitForTimeout(500);

    // Verify the first notification is visible
    const notification1 = page.getByText(/urgent alert received/i);
    await expect(notification1).toBeVisible();

    // Trigger a second urgent alert
    const alertButton2 = page.getByRole('button', { name: /trigger urgent alert/i });
    await expect(alertButton2).toBeVisible();
    await alertButton2.click();

    // Wait for the second notification
    await page.waitForTimeout(500);

    // Verify the second notification is visible and stacked
    const notification2 = page.getByText(/second urgent alert received/i);
    await expect(notification2).toBeVisible();

    // Verify both notifications are visible
    const allNotifications = page.getByText(/urgent alert received|second urgent alert received/i);
    await expect(allNotifications).toHaveCount(2);

    // Verify the notification stacking mechanism is working
    const notificationContainer = page.locator('[data-testid="notification-container"]');
    await expect(notificationContainer).toBeVisible();
  });
});
